module.exports = function (RED) {
    "use strict";

    function InformationServiceNode(n) {
        RED.nodes.createNode(this, n);
        var node = this;

        this.resourceType = n.resourceType;
        this.informationResource = n.informationResource;
        this.func = n.func;

        try {
            // 如果配置界面传过来的是 JSON 字符串，则解析它
            this.params = n.nodeParams ? JSON.parse(n.nodeParams) : [];
        } catch (err) {
            // 如果解析出错（例如格式不对），设为空数组并打印错误
            this.params = [];
            node.error("解析参数列表失败: " + err);
        }

        this.on("input", function (msg, send, done) {
            msg = msg || {};
            msg.resourceType = node.resourceType;
            msg.informationResource = node.informationResource;
            msg.func = node.func;
            send(msg);
            if (done) done();
        });
    }

    RED.nodes.registerType("Information Service", InformationServiceNode);
};